        guestType = aGuestType;
    }

    // guests

    @Override
    public void receiveIn(Room aRoom, String aGuestType) {
        Room.signalRoomIsNotEmpty();
    }

    @Override
    public void receiveWithReservationIn(Room aRoom, String aGuestType) {
